import sys
import csv
import json
from decimal import Decimal, ROUND_HALF_UP


def normalize_category(cat):
    collapsed = ' '.join(cat.split())
    cf = collapsed.casefold()
    if cf == '':
        return 'uncategorized'
    return cf


def fmt(d):
    q = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if q == 0:
        q = Decimal('0.00')
    return str(q)


def main():
    filename = sys.argv[1]
    cats = {}
    total_dec = Decimal('0')

    with open(filename, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            header = None

        if header is None:
            print(json.dumps({"categories": [], "total": "0.00"}))
            return

        for row in reader:
            if len(row) < 3:
                continue
            cat = row[0]
            amt_str = row[1].strip()
            status = row[2]

            if status.strip().casefold() != 'paid':
                continue

            ncat = normalize_category(cat)
            amt = Decimal(amt_str)
            ramt = amt.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

            cats[ncat] = cats.get(ncat, Decimal('0')) + ramt
            total_dec += ramt

    categories_out = []
    for name in sorted(cats.keys()):
        categories_out.append({"category": name, "total": fmt(cats[name])})

    out = {"categories": categories_out, "total": fmt(total_dec)}
    print(json.dumps(out))


if __name__ == '__main__':
    main()
